# Check the objects with year-like names
year_named = df[df['OBJECT_NAME'].str.match(r'^\d{4}-', na=False)]
print(f"Objects with year-like names: {len(year_named)}")
print(year_named[['OBJECT_NAME', 'OBJECT_ID']].head(20))

# Better constellation extraction
def get_constellation(name):
    if pd.isna(name):
        return 'Other/Unclassified'
    name_upper = name.strip().upper()

    # Mega-constellations
    if name_upper.startswith('STARLINK'):
        return 'Starlink'
    elif name_upper.startswith('ONEWEB'):
        return 'OneWeb'
    elif name_upper.startswith('KUIPER'):
        return 'Project Kuiper'
    elif name_upper.startswith('HULIANWANG'):
        return 'Hulianwang (China)'
    elif name_upper.startswith('QIANFAN'):
        return 'Qianfan (G60)'
    elif name_upper.startswith('GEESAT'):
        return 'Geesat'

    # Navigation constellations
    elif name_upper.startswith('GPS') or name_upper.startswith('NAVSTAR'):
        return 'GPS/NAVSTAR'
    elif name_upper.startswith('GLONASS'):
        return 'GLONASS'
    elif name_upper.startswith('GALILEO'):
        return 'Galileo'
    elif name_upper.startswith('BEIDOU'):
        return 'BeiDou'

    # Communications
    elif name_upper.startswith('IRIDIUM'):
        return 'Iridium'
    elif name_upper.startswith('GLOBALSTAR'):
        return 'Globalstar'
    elif name_upper.startswith('ORBCOMM'):
        return 'Orbcomm'
    elif name_upper.startswith('EUTELSAT'):
        return 'Eutelsat'
    elif name_upper.startswith('INMARSAT') or name_upper.startswith('INTELSAT'):
        return 'Inmarsat/Intelsat'
    elif name_upper.startswith('SWARM'):
        return 'Swarm'

    # Earth observation
    elif name_upper.startswith('FLOCK') or name_upper.startswith('DOVE') or name_upper.startswith('SKYSAT'):
        return 'Planet Labs'
    elif name_upper.startswith('LEMUR'):
        return 'Spire (Lemur)'
    elif name_upper.startswith('ICEYE'):
        return 'ICEYE'
    elif name_upper.startswith('COSMO'):
        return 'COSMO-SkyMed'
    elif name_upper.startswith('JILIN'):
        return 'Jilin-1'
    elif name_upper.startswith('GAOFEN'):
        return 'Gaofen'
    elif name_upper.startswith('YAOGAN'):
        return 'Yaogan'
    elif name_upper.startswith('CAPE'):
        return 'CAPE'
    elif name_upper.startswith('HAWK'):
        return 'HawkEye 360'
    elif name_upper.startswith('SITRO'):
        return 'SITRO-AIS'
    elif name_upper.startswith('SHIYAN') or name_upper.startswith('SJ-'):
        return 'Shiyan'
    elif name_upper.startswith('WORLDKINE'):
        return 'Worldkine'

    # Weather/Environmental
    elif name_upper.startswith('NOAA') or name_upper.startswith('GOES') or name_upper.startswith('METOP') or name_upper.startswith('METEOR') or name_upper.startswith('FENGYUN') or name_upper.startswith('HIMAWARI') or name_upper.startswith('SENTINEL'):
        return 'Weather/Env/Sentinel'

    # Transporter rideshare (unnamed objects)
    elif name_upper.startswith('TRANSPORTER'):
        return 'Transporter Rideshare'

    # Year-like names (unnamed/designation only)
    elif name_upper[:4].isdigit() and len(name_upper) > 4:
        return 'Other/Unclassified'

    else:
        return 'Other/Unclassified'

df['CONSTELLATION'] = df['OBJECT_NAME'].apply(get_constellation)
const_counts = df['CONSTELLATION'].value_counts()
print("\n=== CONSTELLATION BREAKDOWN ===")
for c, n in const_counts.items():
    print(f'{c}: {n} ({n/len(df)*100:.1f}%)')

# For top 10 constellation, get orbit regime breakdown
def classify_orbit(mm):
    if mm > 14:
        return 'LEO'
    elif mm >= 2.0:
        return 'MEO'
    elif mm >= 0.9 and mm <= 1.1:
        return 'GEO'
    else:
        return 'HEO'
df['ORBIT_REGIME'] = df['MEAN_MOTION'].apply(classify_orbit)

print("\n=== TOP CONSTELLATION x ORBIT REGIME ===")
top_constellations = const_counts.head(12).index.tolist()
for c in top_constellations:
    sub = df[df['CONSTELLATION'] == c]
    orbit_dist = sub['ORBIT_REGIME'].value_counts()
    print(f'{c}: {dict(orbit_dist)}')

